                  ("flow_run_events"."summary"->>'currentEndAt')::timestamptz
            and length(trim("flow_run_events"."summary"->>'previousTimeZone')) between 1 and 120
            and length(trim("flow_run_events"."summary"->>'currentTimeZone')) between 1 and 120
            and (
